select is(public.phase4_can_read_protected('44003000-0000-4000-8000-000000000211','44003000-0000-4000-8000-000000000111',public.app_today()-1),true,'explicit historical date uses actual historical placement');
select throws_ok($q$select public.phase4_revoke_protected_permission((select id from results where name='grant'))$q$,'42501',null,'admin cannot revoke protection');
select throws_ok($q$select public.phase4_grant_protected_permission((select id from results where name='admin'),'44003000-0000-4000-8000-000000000112')$q$,'42501',null,'admin cannot grant protection');
