update public.access_assignments set valid_to=public.app_today()-1,valid_from=public.app_today()-30 where id='44003000-0000-4000-8000-000000000041';
select is(public.phase4_protected_permission_is_valid((select id from results where name='grant')),false,'giver expired immediately breaks permission');
update public.access_assignments set valid_to=null,valid_from=public.app_today() where id='44003000-0000-4000-8000-000000000041';
update public.access_assignments set valid_to=public.app_today()-1,valid_from=public.app_today()-30 where id=(select id from results where name='admin');
select is(public.phase4_protected_permission_is_valid((select id from results where name='grant')),false,'admin expired immediately breaks permission');
update public.access_assignments set valid_to=null,valid_from=public.app_today() where id=(select id from results where name='admin');

